import{a as e,i as t,s as n,t as r}from"./app-CchzzT6L.js";var i=JSON.parse(`{"path":"/AI/LLM%20Gag/real-world-ep1.html","title":"","lang":"en-US","frontmatter":{},"git":{"updatedTime":1749378724000,"contributors":[{"name":"hifat","username":"hifat","email":"logmanxsa@gmail.com","commits":1,"url":"https://github.com/hifat"}],"changelog":[{"hash":"12e48b94e378386433cc3f7be77fabe628f721c0","time":1749378724000,"email":"logmanxsa@gmail.com","author":"hifat","message":"add llm gag content"}]},"filePathRelative":"AI/LLM Gag/real-world-ep1.md"}`),a={name:`real-world-ep1.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<p>โอเคเพื่อนรัก! 💀🔥</p><p>ถ้าอยากเจอ <strong>real-world machine</strong> ที่บอกเลยว่าเจ็บจริง ท้าจริง และสอนให้โตจริง ๆ — กูมีของดีมาแนะนำ</p><hr><h2 id="💥-real-world-style-machine-แนะนําสําหรับเริ่มต้น-ใน-hackthebox" tabindex="-1"><a class="header-anchor" href="#💥-real-world-style-machine-แนะนําสําหรับเริ่มต้น-ใน-hackthebox"><span>💥 Real-World Style Machine แนะนำสำหรับเริ่มต้น (ใน HackTheBox)</span></a></h2><h3 id="_1-active" tabindex="-1"><a class="header-anchor" href="#_1-active"><span>1. <strong>Active</strong></span></a></h3><ul><li>ระบบ Windows ที่เน้นเจาะช่องโหว่ใน Active Directory</li><li>ต้องใช้เทคนิคหลากหลาย ตั้งแต่แสกน, โจมตีช่องโหว่ SMB, Lateral Movement, และ Privilege Escalation</li><li>เรียนรู้การใช้เครื่องมืออย่าง <code>impacket</code>, <code>BloodHound</code>, และ <code>PowerShell</code></li></ul><h3 id="_2-forest" tabindex="-1"><a class="header-anchor" href="#_2-forest"><span>2. <strong>Forest</strong></span></a></h3><ul><li>เครื่อง Windows ที่จำลอง AD Environment ใหญ่กว่า Active</li><li>เหมาะกับคนที่อยากเจาะ Domain Controller และเข้าใจระบบ Domain จริง ๆ</li><li>ต้องใช้ความรู้ Kerberos, NTLM relay, และโจมตีช่องโหว่ใน AD</li></ul><h3 id="_3-vault" tabindex="-1"><a class="header-anchor" href="#_3-vault"><span>3. <strong>Vault</strong></span></a></h3><ul><li>Linux server ที่เน้นโจมตีบริการจริงในระบบ</li><li>มีการตั้งค่าที่สมจริง มีหลายบริการ เช่น SSH, HTTP, Database</li><li>เหมาะกับคนที่อยากฝึกเจาะ Linux real-world server</li></ul><hr><h2 id="🧰-สิ่งที่ควรเตรียมตัวก่อนลุย" tabindex="-1"><a class="header-anchor" href="#🧰-สิ่งที่ควรเตรียมตัวก่อนลุย"><span>🧰 สิ่งที่ควรเตรียมตัวก่อนลุย</span></a></h2><ul><li><strong>ความรู้พื้นฐาน</strong> Windows/Linux commands</li><li><strong>เครื่องมือ</strong>: Kali Linux, Impacket tools, CrackMapExec, BloodHound</li><li><strong>ทักษะ</strong>: Recon, Enumeration, Exploitation, Privilege Escalation</li><li><strong>ใจ</strong>: ต้องพร้อมเจอความซับซ้อนและอาจเจอ dead-end บ้าง</li></ul><hr><h2 id="🔥-เริ่มยังไงดี" tabindex="-1"><a class="header-anchor" href="#🔥-เริ่มยังไงดี"><span>🔥 เริ่มยังไงดี?</span></a></h2><ol><li><p>เลือกเครื่องใน HTB ที่เป็น real-world (แนะนำ Active หรือ Vault)</p></li><li><p>ลงทะเบียน VPN และเชื่อมต่อให้เรียบร้อย</p></li><li><p>เริ่มสแกนระบบ และทำ Recon โดยละเอียด</p><ul><li>ใช้ <code>nmap</code>, <code>enum4linux</code>, <code>rpcclient</code>, <code>smbclient</code> ฯลฯ</li></ul></li><li><p>ค่อย ๆ วิเคราะห์และหาจุดอ่อน</p></li><li><p>ถ้าติดขัด บอกกู! จะช่วยแนะนำเทคนิคเฉพาะ</p></li></ol><hr><h2 id="💬-สรุป" tabindex="-1"><a class="header-anchor" href="#💬-สรุป"><span>💬 สรุป</span></a></h2><blockquote><p>&quot;แค่นี้ไม่เจ็บเท่าลืมเธอไม่ได้&quot; แต่เจอ real-world machine ที่ถูกต้อง จะทำให้มึงแข็งแกร่งขึ้นกว่าเดิมหลายเท่า</p></blockquote><hr><p>ถ้าพร้อมบอกกู เดี๋ยวกูช่วยแนะนำ walkthrough เบื้องต้น หรือให้เทคนิคยัดเต็มกระบอกเลย!</p>`,21)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};